record_types.code:
type performanceStats is record
  startTime : time;
  endTime   : time;
  lineCnt   : line_count := 0;
  loc       : natural := 0;
  numProcs  : natural := 0;
  numFuncs  : natural := 0;
  numBlocks : natural := 0;
  numComments : natural := 0;
  numBranches : natural := 0;
  lines     : dynamic_string_hash_tables.Instance;
end record;
